package com.prismv.history;

import android.content.Context;
import android.content.SharedPreferences;
import android.net.Uri;
import com.prismv.logging.PrismLogger;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.File;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Locale;

/**
 * CompressionHistoryManager:
 * Central persistent registry for all compressed media generated by Prism-V.
 *
 * Implements:
 * 1. Persistent JSON SharedPreferences storage for all compression jobs.
 * 2. Original-to-Compressed Video Pair Mapping (for instant 1-click Duo Comparison).
 * 3. Total Storage Reclaimed Metrics (aggregate saved bytes & percent reduction).
 * 4. Automatic pruning of deleted files & integrity verification.
 */
public final class CompressionHistoryManager {
    private static final String TAG = "PrismV_History";
    private static final String PREF_NAME = "prism_compression_history";
    private static final String KEY_RECORDS = "key_history_records_json";

    private static CompressionHistoryManager instance;
    private final SharedPreferences prefs;
    private final Context context;

    public static class Record {
        public String id;
        public String title;
        public String originalUriStr;
        public String originalPath;
        public long originalSizeBytes;
        public String compressedPath;
        public long compressedSizeBytes;
        public String mode;
        public int width;
        public int height;
        public int bitrateKbps;
        public int fps;
        public long durationMs;
        public long timestampMs;
        public String formattedDate;
        public double percentReduction;
        public long spaceSavedBytes;
        public boolean isSourceTrashed;
        public String trashedSourcePath;

        public Uri getOriginalUri() {
            if (originalUriStr != null && !originalUriStr.isEmpty()) {
                return Uri.parse(originalUriStr);
            }
            if (originalPath != null && !originalPath.isEmpty()) {
                return Uri.fromFile(new File(originalPath));
            }
            return null;
        }

        public Uri getCompressedUri() {
            if (compressedPath != null && !compressedPath.isEmpty()) {
                return Uri.fromFile(new File(compressedPath));
            }
            return null;
        }

        public boolean isCompressedFileExisting() {
            if (compressedPath == null) return false;
            File f = new File(compressedPath);
            return f.exists() && f.length() > 0;
        }

        public boolean isOriginalFileExisting(Context ctx) {
            if (originalPath != null) {
                File f = new File(originalPath);
                if (f.exists() && f.length() > 0) return true;
            }
            if (originalUriStr != null && originalUriStr.startsWith("content://")) {
                try (android.database.Cursor c = ctx.getContentResolver().query(Uri.parse(originalUriStr), null, null, null, null)) {
                    return c != null && c.getCount() > 0;
                } catch (Exception ignored) {}
            }
            return false;
        }
    }

    private CompressionHistoryManager(Context context) {
        this.context = context.getApplicationContext();
        this.prefs = this.context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE);
    }

    public static synchronized CompressionHistoryManager get(Context context) {
        if (instance == null) {
            instance = new CompressionHistoryManager(context);
        }
        return instance;
    }

    public synchronized void recordCompression(
            String title,
            Uri originalUri,
            String originalPath,
            long originalSize,
            String compressedPath,
            long compressedSize,
            String mode,
            int width,
            int height,
            int bitrateKbps,
            int fps,
            long durationMs) {

        long now = System.currentTimeMillis();
        String id = "hist_" + now;
        SimpleDateFormat sdf = new SimpleDateFormat("MMM dd, yyyy HH:mm", Locale.US);
        String dateStr = sdf.format(new Date(now));

        long saved = Math.max(0, originalSize - compressedSize);
        double pct = (originalSize > 0) ? ((double) saved / originalSize) * 100.0 : 0.0;

        Record record = new Record();
        record.id = id;
        record.title = title != null ? title : "video.mp4";
        record.originalUriStr = (originalUri != null) ? originalUri.toString() : "";
        record.originalPath = originalPath != null ? originalPath : "";
        record.originalSizeBytes = originalSize;
        record.compressedPath = compressedPath != null ? compressedPath : "";
        record.compressedSizeBytes = compressedSize;
        record.mode = mode != null ? mode : "H-ARCH";
        record.width = width;
        record.height = height;
        record.bitrateKbps = bitrateKbps;
        record.fps = fps;
        record.durationMs = durationMs;
        record.timestampMs = now;
        record.formattedDate = dateStr;
        record.percentReduction = pct;
        record.spaceSavedBytes = saved;

        List<Record> list = getRecords();
        // Deduplicate: remove any existing record with the exact same compressedPath
        if (compressedPath != null && !compressedPath.isEmpty()) {
            for (int i = list.size() - 1; i >= 0; i--) {
                Record existing = list.get(i);
                if (existing.compressedPath != null && existing.compressedPath.equals(compressedPath)) {
                    if ((originalUri == null || originalUri.toString().isEmpty()) && existing.originalUriStr != null && !existing.originalUriStr.isEmpty()) {
                        record.originalUriStr = existing.originalUriStr;
                    }
                    if ((originalPath == null || originalPath.isEmpty()) && existing.originalPath != null && !existing.originalPath.isEmpty()) {
                        record.originalPath = existing.originalPath;
                    }
                    list.remove(i);
                }
            }
        }
        // Insert at index 0 so newest is first
        list.add(0, record);
        saveRecords(list);

        PrismLogger.i(TAG, String.format(Locale.US, "Recorded compression: '%s' -> '%s' (Saved %.1f MB, -%.1f%%)",
                title, compressedPath, saved / (1024.0 * 1024.0), pct));
    }

    public synchronized List<Record> getRecords() {
        List<Record> list = new ArrayList<>();
        java.util.HashSet<String> seenPaths = new java.util.HashSet<>();
        String json = prefs.getString(KEY_RECORDS, "[]");
        try {
            JSONArray arr = new JSONArray(json);
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                Record r = new Record();
                r.id = o.optString("id");
                r.title = o.optString("title");
                r.originalUriStr = o.optString("originalUriStr");
                r.originalPath = o.optString("originalPath");
                r.originalSizeBytes = o.optLong("originalSizeBytes");
                r.compressedPath = o.optString("compressedPath");
                r.compressedSizeBytes = o.optLong("compressedSizeBytes");
                r.mode = o.optString("mode");
                r.width = o.optInt("width");
                r.height = o.optInt("height");
                r.bitrateKbps = o.optInt("bitrateKbps");
                r.fps = o.optInt("fps");
                r.durationMs = o.optLong("durationMs");
                r.timestampMs = o.optLong("timestampMs");
                r.formattedDate = o.optString("formattedDate");
                r.percentReduction = o.optDouble("percentReduction");
                r.spaceSavedBytes = o.optLong("spaceSavedBytes");
                r.isSourceTrashed = o.optBoolean("isSourceTrashed", false);
                r.trashedSourcePath = o.optString("trashedSourcePath", "");

                if (r.compressedPath != null && !r.compressedPath.isEmpty()) {
                    if (seenPaths.contains(r.compressedPath)) {
                        continue; // Skip duplicate record for identical output file
                    }
                    seenPaths.add(r.compressedPath);
                }
                list.add(r);
            }
        } catch (Exception e) {
            PrismLogger.e(TAG, "Error parsing history records", e);
        }
        return list;
    }

    public synchronized Record getLatestRecord() {
        List<Record> list = getRecords();
        for (Record r : list) {
            if (r.isCompressedFileExisting()) {
                return r;
            }
        }
        return list.isEmpty() ? null : list.get(0);
    }

    public synchronized void updateRecord(Record updated) {
        if (updated == null) return;
        List<Record> list = getRecords();
        for (int i = 0; i < list.size(); i++) {
            Record r = list.get(i);
            if ((updated.id != null && updated.id.equals(r.id)) ||
                (updated.compressedPath != null && updated.compressedPath.equals(r.compressedPath))) {
                list.set(i, updated);
                saveRecords(list);
                return;
            }
        }
        list.add(0, updated);
        saveRecords(list);
    }

    public synchronized void deleteRecord(String id) {
        List<Record> list = getRecords();
        Record toDelete = null;
        for (Record r : list) {
            if (r.id != null && r.id.equals(id)) {
                toDelete = r;
                break;
            }
        }
        if (toDelete != null) {
            list.remove(toDelete);
            saveRecords(list);
        }
    }

    public synchronized void clearHistory() {
        prefs.edit().remove(KEY_RECORDS).apply();
    }

    public synchronized long getTotalOriginalBytes() {
        long total = 0;
        for (Record r : getRecords()) total += r.originalSizeBytes;
        return total;
    }

    public synchronized long getTotalCompressedBytes() {
        long total = 0;
        for (Record r : getRecords()) total += r.compressedSizeBytes;
        return total;
    }

    public synchronized long getTotalSavedBytes() {
        long total = 0;
        for (Record r : getRecords()) total += r.spaceSavedBytes;
        return total;
    }

    private void saveRecords(List<Record> list) {
        try {
            JSONArray arr = new JSONArray();
            for (Record r : list) {
                JSONObject o = new JSONObject();
                o.put("id", r.id);
                o.put("title", r.title);
                o.put("originalUriStr", r.originalUriStr);
                o.put("originalPath", r.originalPath);
                o.put("originalSizeBytes", r.originalSizeBytes);
                o.put("compressedPath", r.compressedPath);
                o.put("compressedSizeBytes", r.compressedSizeBytes);
                o.put("mode", r.mode);
                o.put("width", r.width);
                o.put("height", r.height);
                o.put("bitrateKbps", r.bitrateKbps);
                o.put("fps", r.fps);
                o.put("durationMs", r.durationMs);
                o.put("timestampMs", r.timestampMs);
                o.put("formattedDate", r.formattedDate);
                o.put("percentReduction", r.percentReduction);
                o.put("spaceSavedBytes", r.spaceSavedBytes);
                o.put("isSourceTrashed", r.isSourceTrashed);
                o.put("trashedSourcePath", r.trashedSourcePath);
                arr.put(o);
            }
            prefs.edit().putString(KEY_RECORDS, arr.toString()).apply();
        } catch (Exception e) {
            PrismLogger.e(TAG, "Error saving history records", e);
        }
    }
}
